// Generates supabase/03_seed.sql from the demo catalog.
// Run with:  node scripts/generate-seed.js
import { writeFileSync } from 'node:fs'
import { demoCategories, demoProducts } from '../src/services/demoData.js'

const q = (text) => `'${String(text).replace(/'/g, "''")}'`

let sql = `-- =====================================================================
-- ShopSphere - STEP 3: DEMO DATA (5 categories, ${demoProducts.length} products)
-- Generated by scripts/generate-seed.js - do not edit by hand.
-- Run after 01_schema.sql and 02_policies.sql.
-- =====================================================================

insert into public.categories (name, slug, description, image_url) values
${demoCategories
  .map((c) => `  (${q(c.name)}, ${q(c.slug)}, ${q(c.description)}, ${q(c.image_url)})`)
  .join(',\n')}
on conflict (slug) do nothing;

insert into public.products
  (name, description, price, discount_percent, category_id, image_url, rating, stock, sales_count, created_at)
values
${demoProducts
  .map(
    (p) =>
      `  (${q(p.name)}, ${q(p.description)}, ${p.price}, ${p.discount_percent}, ` +
      `(select id from public.categories where slug = ${q(p.category_id)}), ` +
      `${q(p.image_url)}, ${p.rating}, ${p.stock}, ${p.sales_count}, now() - interval '${p.daysAgo} days')`,
  )
  .join(',\n')};
`

writeFileSync(new URL('../supabase/03_seed.sql', import.meta.url), sql)
console.log(`Wrote supabase/03_seed.sql with ${demoProducts.length} products`)

